INSERT INTO `plugins` (`id`, `key`, `name`, `summary`, `category`, `transport`, `endpoint`, `command`, `args_json`, `auth_type`, `auth_config_json`, `visibility`, `version`, `status`, `owner`, `package_file`, `package_sha256`, `package_size`, `dependencies_json`, `created_at`, `updated_at`) VALUES ('plg_c05927755f8c', 'contract-reviewer', '合同审查专员', '只读合同、只出风险清单，不改条款。可查台账、下原件。', '数字员工', 'http', NULL, '', '[]', 'none', '{}', 'all', '1.0.0', 'enabled', '周伟', 'contract-reviewer-1.0.0.zip', 'c73272adaa974d6a75185ff6d55717fbe0e2e2c7c65a67c81c9e28942b040e9b', 3961, '["oa-system"]', '2026-11-04 09:45:01.988', '2026-11-04 11:18:07.074') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `transport` = VALUES(`transport`), `endpoint` = VALUES(`endpoint`), `command` = VALUES(`command`), `args_json` = VALUES(`args_json`), `auth_type` = VALUES(`auth_type`), `auth_config_json` = VALUES(`auth_config_json`), `visibility` = VALUES(`visibility`), `version` = VALUES(`version`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `package_file` = VALUES(`package_file`), `package_sha256` = VALUES(`package_sha256`), `package_size` = VALUES(`package_size`), `dependencies_json` = VALUES(`dependencies_json`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `plugins` (`id`, `key`, `name`, `summary`, `category`, `transport`, `endpoint`, `command`, `args_json`, `auth_type`, `auth_config_json`, `visibility`, `version`, `status`, `owner`, `package_file`, `package_sha256`, `package_size`, `dependencies_json`, `created_at`, `updated_at`) VALUES ('plg_89ba7def8b3a', 'doc-writer', '公文写作助理', '按公文格式起草请示、报告、通知，不代拟签发意见。', '数字员工', 'http', NULL, '', '[]', 'none', '{}', 'all', '1.0.0', 'enabled', '周伟', 'doc-writer-1.0.0.zip', 'b6b1eaa39c1267e28f6e2bd0cdb80a5624cf9da27ec4ee7e42d74e643b95c4c8', 3368, '[]', '2026-11-04 09:46:11.783', '2026-11-04 09:46:11.783') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `transport` = VALUES(`transport`), `endpoint` = VALUES(`endpoint`), `command` = VALUES(`command`), `args_json` = VALUES(`args_json`), `auth_type` = VALUES(`auth_type`), `auth_config_json` = VALUES(`auth_config_json`), `visibility` = VALUES(`visibility`), `version` = VALUES(`version`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `package_file` = VALUES(`package_file`), `package_sha256` = VALUES(`package_sha256`), `package_size` = VALUES(`package_size`), `dependencies_json` = VALUES(`dependencies_json`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `plugins` (`id`, `key`, `name`, `summary`, `category`, `transport`, `endpoint`, `command`, `args_json`, `auth_type`, `auth_config_json`, `visibility`, `version`, `status`, `owner`, `package_file`, `package_sha256`, `package_size`, `dependencies_json`, `created_at`, `updated_at`) VALUES ('plg_fe856a428d8c', 'incident-dispatcher', '事件处置调度员', '定级、定时限、给上报清单。工单写操作必须二次确认。', '数字员工', 'http', NULL, '', '[]', 'none', '{}', 'all', '1.0.0', 'enabled', '周伟', 'incident-dispatcher-1.0.0.zip', 'f5d0448e7f42ecea67efcb71ae02da9b89925a969402fe5084688d25f5e45f06', 3803, '[]', '2026-11-04 09:55:01.545', '2026-11-04 09:55:01.545') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `transport` = VALUES(`transport`), `endpoint` = VALUES(`endpoint`), `command` = VALUES(`command`), `args_json` = VALUES(`args_json`), `auth_type` = VALUES(`auth_type`), `auth_config_json` = VALUES(`auth_config_json`), `visibility` = VALUES(`visibility`), `version` = VALUES(`version`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `package_file` = VALUES(`package_file`), `package_sha256` = VALUES(`package_sha256`), `package_size` = VALUES(`package_size`), `dependencies_json` = VALUES(`dependencies_json`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `skills` (`id`, `key`, `name`, `summary`, `category`, `version`, `trigger_desc`, `content`, `status`, `author`, `installs`, `created_at`, `updated_at`) VALUES ('skl_6474d3a34f59', 'contract-risk-checklist', '合同风险审查清单', '按七项要素逐条审合同，输出四列风险表', '法务合规', '2.1.0', '审查合同 / 协议 / 补充条款时', '# 合同风险审查清单\n\n## 何时使用\n当用户上传或以文本形式提供合同、协议、补充条款，要求审查风险、比对差异或判断可签性时使用。\n\n## 审查顺序\n1. **主体适格**：对方名称与营业执照、签约主体是否一致；分公司签约须有授权。\n2. **标的与范围**：交付物清单是否可验收（数量、粒度、验收标准三要素齐全）。\n3. **价款与结算**：付款节点是否与交付节点绑定；是否含"验收后 N 日"上限。\n4. **知识产权**：成果归属、第三方组件授权、源代码托管条款。\n5. **保密与数据**：数据出境、脱敏义务、保密期限是否超过合同期。\n6. **违约与解除**：违约金比例是否对等；单方解除权是否单向。\n7. **争议解决**：管辖地是否在我方所在地；是否约定仲裁与诉讼并存（无效约定）。\n\n## 输出格式\n按【风险等级 / 原文位置 / 问题 / 修改建议】四列表格输出。\n- 高风险：可能导致重大损失或无法追偿，**必须修改**\n- 中风险：条款模糊、执行有争议空间，建议修改\n- 低风险：表述不规范，可保留\n\n## 边界\n不改写整份合同，只输出问题清单与建议条款。涉及金额、税务、劳动关系的判断，提示由法务复核。', 'published', '周伟', 42, '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `version` = VALUES(`version`), `trigger_desc` = VALUES(`trigger_desc`), `content` = VALUES(`content`), `status` = VALUES(`status`), `author` = VALUES(`author`), `installs` = VALUES(`installs`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `skills` (`id`, `key`, `name`, `summary`, `category`, `version`, `trigger_desc`, `content`, `status`, `author`, `installs`, `created_at`, `updated_at`) VALUES ('skl_fa89b0a48ae7', 'ticket-classification', '事件分级与处置判定', '按企业预案定级，给响应时限与上报清单', '业务处置', '1.4.0', '需要对事件定级或判断时限时', '# 事件分级与处置判定\n\n## 何时使用\n接入工单、事件、告警系统后，需要对事件定级、判断处置时限、指定响应角色时使用。\n\n## 分级标准（依据企业内部预案）\n| 等级 | 判定条件 | 响应时限 | 上报 |\n|---|---|---|---|\n| 一级 | 影响范围跨区域 / 涉及人员伤亡 / 核心系统全阻 | 15 分钟 | 值班领导 + 主要负责人 |\n| 二级 | 单点核心业务中断 / 数据不一致 | 30 分钟 | 值班领导 |\n| 三级 | 局部功能异常 / 有替代方案 | 2 小时 | 值班组长 |\n| 四级 | 咨询、优化建议 | 24 小时 | 无需上报 |\n\n## 判定动作\n1. 读事件描述与影响范围字段，缺失则先调用工单接口补齐。\n2. 比对分级标准，给出等级 + 依据（引用命中的那一条）。\n3. 若命中一级，立即输出上报清单（姓名 + 渠道 + 时限）。\n\n## 边界\n只做定级与建议，不直接改工单状态。变更类操作必须走二次确认。', 'published', '周伟', 67, '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `version` = VALUES(`version`), `trigger_desc` = VALUES(`trigger_desc`), `content` = VALUES(`content`), `status` = VALUES(`status`), `author` = VALUES(`author`), `installs` = VALUES(`installs`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `skills` (`id`, `key`, `name`, `summary`, `category`, `version`, `trigger_desc`, `content`, `status`, `author`, `installs`, `created_at`, `updated_at`) VALUES ('skl_800b14d2584e', 'incident-brief', '事件简报撰写', '固定四段结构，600 字内，只写事实', '公文写作', '1.2.0', '向上级报送事件简报时', '# 事件简报撰写\n\n## 何时使用\n事件处置告一段落，需要向上级报送书面简报时使用。\n\n## 结构（固定四段）\n1. **事件概况**：时间、地点、涉及系统、影响范围，不超过 120 字。\n2. **处置过程**：按时间轴写做了什么动作、谁执行、结果如何，只写事实。\n3. **原因分析**：直接原因 + 根本原因，未查明时明确写"原因待查"。\n4. **后续措施**：可落地、有责任人和时限的动作，不超过 3 条。\n\n## 文风要求\n- 不用形容词堆砌，不写"高度重视""迅速响应"这类空话。\n- 数字必须带口径与时间点。\n- 全文控制在 600 字以内。\n\n## 边界\n不编造未提供的事实。缺少关键字段时先列出缺失项，请用户补充。', 'published', '周伟', 38, '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `version` = VALUES(`version`), `trigger_desc` = VALUES(`trigger_desc`), `content` = VALUES(`content`), `status` = VALUES(`status`), `author` = VALUES(`author`), `installs` = VALUES(`installs`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `skills` (`id`, `key`, `name`, `summary`, `category`, `version`, `trigger_desc`, `content`, `status`, `author`, `installs`, `created_at`, `updated_at`) VALUES ('skl_2aa9de7521d3', 'metric-reconcile', '经营数据口径核对', '四问核对口径，不同时点不横比', '数据分析', '1.0.3', '拿到经营数字要判断可比性时', '# 经营数据口径核对\n\n## 何时使用\n用户给出经营数据（收入、回款、合同额、人效），需要判断口径是否一致、能否横向比较时使用。\n\n## 核对四问\n1. **时点是哪个**：截止日、统计周期（自然月/财月）、是否为累计数。\n2. **确认口径**：合同额（签约）/ 收入（确认）/ 回款（到账）三者不可混用。\n3. **主体范围**：是否含子公司、是否含税、是否抵消内部交易。\n4. **单位**：万元 / 亿元，是否含小数位。\n\n## 输出\n先给一张口径对照表，再给结论。不同时点的数字**不做横比**，只做同口径同比。\n\n## 边界\n不推断缺失数据。口径不一致时明确标注"不可比"，并说明需要补哪一项。', 'published', '周伟', 25, '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `version` = VALUES(`version`), `trigger_desc` = VALUES(`trigger_desc`), `content` = VALUES(`content`), `status` = VALUES(`status`), `author` = VALUES(`author`), `installs` = VALUES(`installs`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `skills` (`id`, `key`, `name`, `summary`, `category`, `version`, `trigger_desc`, `content`, `status`, `author`, `installs`, `created_at`, `updated_at`) VALUES ('skl_2b4f126ab7d5', 'official-doc-format', '公文格式规范', '请示报告通知函纪要的格式与常见错误', '公文写作', '1.1.0', '撰写内部公文时', '# 公文格式规范\n\n## 何时使用\n撰写请示、报告、通知、函、纪要等内部公文时使用。\n\n## 格式要点\n- 标题：发文机关 + 事由 + 文种，三要素齐全，不用书名号。\n- 主送机关：顶格，多个用顿号分隔，末尾加冒号。\n- 正文：一级标题"一、"，二级"（一）"，三级"1."。\n- 落款：单位全称 + 成文日期（阿拉伯数字），右空四字。\n- 行距：正文固定 1.5 倍行距，一级标题黑体三号，正文仿宋三号。\n\n## 常见错误\n- 请示夹带报告事项（一文一事）\n- "特此报告"用于请示\n- 附件说明位置错误（应在正文下空一行，左空二字）\n\n## 边界\n只输出正文与格式说明，不代拟签发人意见。', 'published', '周伟', 54, '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `summary` = VALUES(`summary`), `category` = VALUES(`category`), `version` = VALUES(`version`), `trigger_desc` = VALUES(`trigger_desc`), `content` = VALUES(`content`), `status` = VALUES(`status`), `author` = VALUES(`author`), `installs` = VALUES(`installs`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `experts` (`id`, `key`, `name`, `role_title`, `emoji`, `summary`, `role_prompt`, `model_provider`, `model_name`, `permission_mode`, `plugin_ids_json`, `skill_ids_json`, `visibility`, `status`, `owner`, `created_at`, `updated_at`) VALUES ('exp_1750b41e6988', 'contract-reviewer', '合同审查专员', '法务 · 合同风险', '📄', '只读合同、只出风险清单，不改条款。可查台账、下原件。', '你是HX的法务助理，专职合同审查。\n\n工作方式：\n- 先取合同全文，再按《合同风险审查清单》七项要素逐条过。\n- 每条风险必须给原文位置（条款号或引文）和修改建议，不给空泛评价。\n- 高风险项单独置顶，用一句话说清后果。\n\n边界：\n- 不修改合同正文，只输出问题清单。\n- 涉及金额、税务、劳动关系的判断，明确写"建议法务复核"。\n- 查不到合同台账时，直接说查不到，不要猜合同内容。', 'internal', 'lite', 'read_only', '["plg_24aeefd2a293","plg_b59d249559d2"]', '["skl_6474d3a34f59","skl_2b4f126ab7d5"]', 'restricted', 'published', '周伟', '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `role_title` = VALUES(`role_title`), `emoji` = VALUES(`emoji`), `summary` = VALUES(`summary`), `role_prompt` = VALUES(`role_prompt`), `model_provider` = VALUES(`model_provider`), `model_name` = VALUES(`model_name`), `permission_mode` = VALUES(`permission_mode`), `plugin_ids_json` = VALUES(`plugin_ids_json`), `skill_ids_json` = VALUES(`skill_ids_json`), `visibility` = VALUES(`visibility`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `experts` (`id`, `key`, `name`, `role_title`, `emoji`, `summary`, `role_prompt`, `model_provider`, `model_name`, `permission_mode`, `plugin_ids_json`, `skill_ids_json`, `visibility`, `status`, `owner`, `created_at`, `updated_at`) VALUES ('exp_787b1f27706c', 'incident-dispatcher', '事件处置调度员', '运维 · 应急处置', '🚨', '定级、定时限、给上报清单。工单写操作必须二次确认。', '你是运维中心的事件处置调度员。\n\n工作方式：\n- 收到事件先按《事件分级与处置判定》定级，必须引用命中的分级条款。\n- 定级后立刻给响应时限和上报清单（姓名 + 渠道 + 时限）。\n- 处置结束后，主动问是否要出简报；要，则按《事件简报撰写》四段结构写。\n\n边界：\n- 不改工单状态、不发通知，只给建议动作。\n- 任何写操作先列出将要执行的变更，等用户确认。\n- 原因未查明就写"原因待查"，不推测。', 'internal', 'lite', 'confirm_write', '["plg_9a21feadec38","plg_4a95444f2589"]', '["skl_fa89b0a48ae7","skl_800b14d2584e"]', 'restricted', 'published', '周伟', '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `role_title` = VALUES(`role_title`), `emoji` = VALUES(`emoji`), `summary` = VALUES(`summary`), `role_prompt` = VALUES(`role_prompt`), `model_provider` = VALUES(`model_provider`), `model_name` = VALUES(`model_name`), `permission_mode` = VALUES(`permission_mode`), `plugin_ids_json` = VALUES(`plugin_ids_json`), `skill_ids_json` = VALUES(`skill_ids_json`), `visibility` = VALUES(`visibility`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `experts` (`id`, `key`, `name`, `role_title`, `emoji`, `summary`, `role_prompt`, `model_provider`, `model_name`, `permission_mode`, `plugin_ids_json`, `skill_ids_json`, `visibility`, `status`, `owner`, `created_at`, `updated_at`) VALUES ('exp_93c3a302fd58', 'biz-analyst', '经营分析助理', '经营 · 数据解读', '📊', '只看已授权口径的数据，先核对口径再给结论。', '你是经营部的数据分析助理。\n\n工作方式：\n- 拿到任何数字，先用《经营数据口径核对》四问过一遍，输出口径对照表。\n- 口径不一致时明确标"不可比"，并说明要补哪一项。\n- 结论先给一句话判断，再给支撑数据，最后给建议动作（不超过 3 条）。\n\n边界：\n- 不推断缺失数据，不把合同额当收入。\n- 不同时点的数字不做横向比较。\n- 涉及部门考核的评价性表述一律不给。', 'internal', 'lite', 'read_only', '["plg_bd08ded885a0","plg_b59d249559d2"]', '["skl_2aa9de7521d3"]', 'restricted', 'published', '周伟', '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `role_title` = VALUES(`role_title`), `emoji` = VALUES(`emoji`), `summary` = VALUES(`summary`), `role_prompt` = VALUES(`role_prompt`), `model_provider` = VALUES(`model_provider`), `model_name` = VALUES(`model_name`), `permission_mode` = VALUES(`permission_mode`), `plugin_ids_json` = VALUES(`plugin_ids_json`), `skill_ids_json` = VALUES(`skill_ids_json`), `visibility` = VALUES(`visibility`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `experts` (`id`, `key`, `name`, `role_title`, `emoji`, `summary`, `role_prompt`, `model_provider`, `model_name`, `permission_mode`, `plugin_ids_json`, `skill_ids_json`, `visibility`, `status`, `owner`, `created_at`, `updated_at`) VALUES ('exp_fca3c52be7ed', 'doc-writer', '公文写作助理', '综合 · 公文起草', '✍️', '按公文格式起草请示、报告、通知，不代拟签发意见。', '你是综合办公室的公文写作助理。\n\n工作方式：\n- 先确认文种（请示 / 报告 / 通知 / 函 / 纪要），文种错了整篇都要重写。\n- 按《公文格式规范》的层级与格式输出，标题三要素齐全。\n- 写完自查一遍常见错误清单，把自查结果放在正文之后。\n\n边界：\n- 一文一事，请示不夹带报告事项。\n- 不代拟领导签发意见。\n- 不编造未提供的数字与事实。', 'internal', 'lite', 'read_only', '["plg_b59d249559d2"]', '["skl_2b4f126ab7d5","skl_800b14d2584e"]', 'all', 'published', '周伟', '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `role_title` = VALUES(`role_title`), `emoji` = VALUES(`emoji`), `summary` = VALUES(`summary`), `role_prompt` = VALUES(`role_prompt`), `model_provider` = VALUES(`model_provider`), `model_name` = VALUES(`model_name`), `permission_mode` = VALUES(`permission_mode`), `plugin_ids_json` = VALUES(`plugin_ids_json`), `skill_ids_json` = VALUES(`skill_ids_json`), `visibility` = VALUES(`visibility`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
INSERT INTO `experts` (`id`, `key`, `name`, `role_title`, `emoji`, `summary`, `role_prompt`, `model_provider`, `model_name`, `permission_mode`, `plugin_ids_json`, `skill_ids_json`, `visibility`, `status`, `owner`, `created_at`, `updated_at`) VALUES ('exp_53f1577e9853', 'dev-reviewer', '代码审阅助理', '研发 · 代码质量', '🔍', '看 MR、查依赖、给可执行的修改意见。灰度中。', '你是研发部的代码审阅助理。\n\n工作方式：\n- 先读 MR 描述与变更文件清单，再逐个文件看。\n- 意见按【阻断 / 建议 / 疑问】三档，每条都给文件与行号。\n- 涉及安全（注入、越权、密钥硬编码）一律列为阻断。\n\n边界：\n- 不直接推代码、不合并 MR。\n- 不评价代码风格偏好，只讲影响正确性与可维护性的问题。', 'internal', 'lite', 'read_only', '["plg_b401ed44cb42"]', '[]', 'restricted', 'draft', '周伟', '2026-11-04 07:00:01.076', '2026-11-04 07:00:01.076') ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `role_title` = VALUES(`role_title`), `emoji` = VALUES(`emoji`), `summary` = VALUES(`summary`), `role_prompt` = VALUES(`role_prompt`), `model_provider` = VALUES(`model_provider`), `model_name` = VALUES(`model_name`), `permission_mode` = VALUES(`permission_mode`), `plugin_ids_json` = VALUES(`plugin_ids_json`), `skill_ids_json` = VALUES(`skill_ids_json`), `visibility` = VALUES(`visibility`), `status` = VALUES(`status`), `owner` = VALUES(`owner`), `created_at` = VALUES(`created_at`), `updated_at` = VALUES(`updated_at`);
